'QZ_Tray_Printer' => 'QZ Tray (pencetak pada komputer ini)',
'QZ_Printer_Name_Hint' => 'Nama pencetak seperti yang dipaparkan pada komputer yang menjalankan QZ Tray. Biarkan kosong untuk menggunakan pencetak lalai komputer tersebut. Klik ⟳ untuk mengesan pencetak.',
'QZ_Not_Running' => 'QZ Tray tidak berjalan pada komputer ini. Pasangnya dari qz.io dan biarkan ia berjalan, kemudian benarkan laman web ini apabila QZ meminta.',
'Detect_Printers' => 'Kesan pencetak',
'QZ_Download_Cert' => 'Muat turun sijil (override.crt)',
'QZ_Setup_Title' => 'Cara menyediakan pencetakan QZ Tray (sekali sahaja, pada setiap komputer yang mencetak label)',
'QZ_Step_Install' => '1. Pasang QZ Tray pada komputer ini — muat turunnya secara percuma dari qz.io, kemudian mulakannya dan biarkan ia berjalan (ia berada dalam dulang sistem di Windows atau bar menu di macOS).',
'QZ_Step_Connect' => '2. Sambungkan pencetak label anda melalui USB dan pastikan ia dipasang dalam sistem pengendalian (Windows: Settings > Printers & scanners — macOS: System Settings > Printers & Scanners).',
'QZ_Step_Detect' => '3. Klik butang ⟳ di sebelah "Nama pencetak" di atas untuk mengesan pencetak pada komputer ini, kemudian pilih pencetak label anda. Biarkan medan kosong untuk menggunakan pencetak lalai komputer.',
'QZ_Step_Cert' => '4. Untuk mencetak tanpa tetingkap timbul kebenaran, muat turun sijil di bawah dan salinnya ke dalam folder pemasangan QZ Tray, dinamakan semula sebagai override.crt (Windows: C:\\Program Files\\QZ Tray — macOS: /Applications/QZ Tray.app/Contents/Resources — Linux: /opt/qz-tray). Kemudian tutup QZ Tray dan mulakannya semula.',
'QZ_Step_Test' => '5. Klik "Cetak label ujian" di bawah. Jika QZ Tray meminta kebenaran, klik Allow — dengan sijil dipasang, ia tidak akan meminta lagi.',
'QZ_Step_Save' => '6. Klik Hantar untuk menyimpan tetapan ini. Label dari halaman Cetak Kod Bar kini akan dicetak terus pada pencetak ini, tanpa dialog cetakan pelayar.',
'QZ_Setup_Note' => 'QZ Tray berjalan pada komputer yang anda gunakan untuk melayari, jadi ini berfungsi walaupun Stocky dihoskan pada pelayan jauh. Setiap komputer yang mencetak label perlu memasang QZ Tray.',

