'Label_Size_Hint' => 'Saiz fizikal satu pelekat pada gulungan. Ia mesti sepadan tepat dengan label yang dimuatkan — saiz yang salah menyebabkan pencetak mencari jarak di tempat yang salah, jadi setiap label dicetak semakin tersasar.',
