'Dpi_Test_Sent' => 'Dua label sedang dicetak, bertanda 203 dan 300. Yang betul menunjukkan segi empat tepat lengkap dengan jidar kecil yang sekata di keempat-empat sisi — tetapkan "Resolusi kepala cetak" kepada nombor tersebut dan simpan.',
'Label_Offset_X' => 'Ofset mendatar (mm)',
