'Upd_Note_Code_Changes_Lost' => 'Nota 1: Jika anda telah membuat sebarang perubahan dalam kod secara manual, perubahan anda akan hilang.',
'Upd_Manual_Steps_Intro' => 'Sila ikut langkah-langkah ini untuk mengemas kini aplikasi anda',
'Upd_Note_Permission_Only' => 'Nota 2: hanya pentadbir atau pengguna yang mempunyai kebenaran "{perm}" boleh menaik taraf sistem',
'Upd_Manual_Step_Backup_Db' => 'Buat sandaran pangkalan data anda. Pergi ke {backup}, klik Jana Sandaran — anda akan menemuinya dalam {path} — atau eksport pangkalan data anda dari PhpMyAdmin dan simpan ke PC anda.',
'Upd_Manual_Step_Backup_Files' => 'Buat sandaran fail anda sebelum mengemas kini.',
'Upd_Manual_Step_Download' => 'Muat turun versi terkini dari akaun CodeCanyon anda dan ekstraknya.',
'Upd_Manual_Step_Remove' => 'Buang fail sebelumnya, {except}:',
'Upd_Except' => 'kecuali',
'Upd_File_Label' => 'fail: {name}',
'Upd_Folder_Label' => 'folder: {name}',
'Upd_Manual_Step_Reupload' => 'Muat naik semula fail dan folder daripada kemas kini baharu, {except} tiga laluan yang sama di atas.',
'Upd_Manual_Step_Visit' => 'Lawati {url} untuk mengemas kini pangkalan data anda.',
'Upd_Manual_Step_Clear_Cache' => 'Kosongkan cache pelayar anda sepenuhnya.',
'Upd_Manual_Step_Done' => 'Selesai! Nikmati aplikasi yang telah dikemas kini.',
'Upd_Note_Blank_Pages' => 'Nota: Jika mana-mana halaman tidak dimuatkan atau kosong, pastikan anda telah mengosongkan cache pelayar anda.',
'Upd_Guide_Before_Title' => '1. Sebelum anda mengemas kini',
'Upd_Guide_Before_Download' => 'Muat turun {package} aplikasi dari akaun CodeCanyon anda ({path}). Jangan ekstraknya — pengemas kini memerlukan ZIP tepat seperti yang dimuat turun.',
'Upd_Latest_Full_Zip' => 'pakej ZIP penuh terkini',
'Upd_Guide_Before_Admin' => 'Pastikan anda log masuk sebagai pentadbir yang mempunyai kebenaran {perm}. Tiada orang lain boleh melihat atau menjalankan pengemas kini.',
'Upd_Guide_Before_Quiet' => 'Pilih masa yang tenang: semasa kemas kini aplikasi bertukar ke mod penyelenggaraan untuk seketika dan pengguna lain dikunci keluar.',
'Upd_Guide_Before_No_Manual' => 'Anda {not} perlu membuat sandaran secara manual, mengekstrak fail, menjalankan arahan, mengedit fail konfigurasi, atau menyentuh pangkalan data — pengemas kini melakukan semua itu secara automatik. (Sandaran manual tambahan tentu tidak merugikan.)',
'Upd_Not' => 'tidak',
'Upd_Guide_Code_Overwritten' => 'Jika anda telah mengubah suai kod aplikasi secara manual, perubahan anda akan ditimpa oleh kemas kini. Data, muat naik, tetapan dan .env anda sentiasa dikekalkan.',
'Upd_Guide_Running_Title' => '2. Menjalankan kemas kini',
'Upd_Guide_Run_Open' => 'Buka {path} (halaman ini) dan kekal di tab {tab}.',
'Upd_Guide_Run_Upload' => '{upload}: klik atau seret pakej yang dimuat turun ke dalam kotak muat naik. Fail besar dimuat naik dalam cebisan kecil, jadi ini juga berfungsi pada pengehosan kongsi dengan had muat naik yang rendah. Checksum melindungi daripada muat naik yang rosak atau tidak lengkap.',
'Upd_Upload_The_Zip' => 'Muat naik ZIP',
'Upd_Guide_Run_Validation' => '{auto} selepas muat naik (anda boleh menjalankannya semula dengan butang {button}). Sistem menyemak: integriti ZIP, struktur dan kelengkapan pakej, keserasian versi (penurunan versi ditolak), versi dan sambungan PHP yang diperlukan, kebenaran fail, ruang cakera kosong, sambungan pangkalan data, konfigurasi, dan bahawa tiada kemas kini lain sedang berjalan.',
'Upd_Validation_Runs_Automatically' => 'Pengesahan berjalan secara automatik',
'Upd_Guide_Run_Review' => 'Semak panel {panel}. Butang {button} hanya dipaparkan apabila setiap semakan kritikal lulus. Jika semakan gagal, mesej memberitahu anda dengan tepat apa yang perlu dibetulkan.',
'Upd_Guide_Run_Click' => 'Klik {button} dan sahkan. Kemudian hanya {keep} dan perhatikan rel kemajuan. Sistem melaksanakan, mengikut urutan:',
'Upd_Keep_Page_Open' => 'biarkan halaman ini terbuka',
'Upd_Guide_Phase_Backup' => '{label} — longgokan pangkalan data penuh, ZIP setiap fail aplikasi yang boleh diubah oleh kemas kini, dan salinan {env} dicipta dan {verified}. Muat naik anda ({images}) dan {storage} tidak pernah disentuh oleh kemas kini, jadi ia tidak diarkibkan. Jika sandaran tidak dapat dicipta, kemas kini berhenti di sini dan tiada apa-apa diubah.',
'Upd_Verified' => 'disahkan',
'Upd_Guide_Phase_Prepare' => '{label} — versi baharu diekstrak ke kawasan pementasan dan disahkan sekali lagi. Aplikasi langsung masih tidak disentuh.',
'Upd_Guide_Phase_Maintenance' => '{label} — mod penyelenggaraan didayakan; pelawat melihat skrin mesra "Kami akan kembali sebentar lagi".',
'Upd_Guide_Phase_Files' => '{label} — fail baharu ditukar masuk hampir serta-merta; fail lama disimpan di tepi untuk pengembalian. Laluan dilindungi ({env}, {storage}, {images}) tidak pernah diganti.',
'Upd_Guide_Phase_Database' => '{label} — migrasi dijalankan, kemudian kebenaran, terjemahan dan templat disegarkan.',
'Upd_Guide_Phase_Cache' => '{label} — semua cache dikosongkan dan dibina semula.',
'Upd_Guide_Phase_Verify' => '{label} — semakan kesihatan mengesahkan versi baharu dapat dimulakan, pangkalan data berfungsi, semua migrasi telah dijalankan, dan konfigurasi adalah sah.',
'Upd_Guide_Phase_Done' => '{label} — mod penyelenggaraan ditamatkan dan fail sementara dibersihkan.',
'Upd_Guide_Run_Success' => 'Apabila anda melihat {success}, klik {reload} dan segar semula pelayar anda sepenuhnya ({keys}) supaya aset panel pentadbir baharu dimuatkan.',
'Upd_Update_Successful_Short' => 'Kemas kini berjaya',
'Upd_Guide_No_Internet' => 'Tiada sambungan internet diperlukan semasa kemas kini — semuanya datang daripada ZIP yang dimuat naik. Kehilangan sambungan atau menutup pelayar TIDAK merosakkan kemas kini: pelayan mengingati dengan tepat di mana ia berhenti.',
'Upd_Guide_Wrong_Title' => '3. Jika berlaku masalah',
'Upd_Guide_Wrong_Rollback' => '{label} — jika apa-apa gagal selepas fail mula berubah (ralat pengekstrakan, kegagalan migrasi, semakan kesihatan gagal, cakera penuh, …), sistem secara automatik memulihkan fail sebelumnya dan pangkalan data daripada sandaran yang disahkan, menamatkan mod penyelenggaraan, dan melaporkan {message}. Anda kembali tepat di tempat anda bermula.',
'Upd_Automatic_Rollback' => 'Pengembalian automatik',
'Upd_Failed_Previous_Restored' => 'Kemas kini gagal — versi sebelumnya dipulihkan',
'Upd_Guide_Wrong_Interrupted' => '{label} (pelayan dimulakan semula, tamat masa, pelayar ditutup, gangguan bekalan elektrik) — apabila anda membuka semula halaman ini, sepanduk merah menawarkan dua pilihan selamat: {resume} (menyambung semula dari langkah tepat di mana ia berhenti) atau {rollback} (memulihkan versi sebelumnya daripada sandaran).',
'Upd_Interrupted_Update' => 'Kemas kini terganggu',
'Upd_Guide_Wrong_Unreachable' => '{label} — gunakan {console} kendiri di {path}. Ia berfungsi walaupun laman dalam mod penyelenggaraan atau aset panel pentadbir rosak, dan menawarkan tindakan Teruskan / Kembalikan yang sama. Terdapat juga pautan "Akses pentadbir" yang tidak menonjol di bahagian bawah skrin penyelenggaraan.',
'Upd_Admin_Unreachable' => 'Panel pentadbir tidak dapat dicapai',
'Upd_Recovery_Console' => 'konsol pemulihan',
'Upd_Guide_Wrong_Locked_Out' => '{label} — semasa kemas kini sedang berjalan, halaman ini memaparkan {link}. Simpannya jika anda perlu masuk semula (contohnya selepas sesi anda tamat); ia membenarkan anda melepasi skrin penyelenggaraan supaya anda boleh log masuk semula.',
'Upd_Locked_Out_Maintenance' => 'Dikunci keluar oleh mod penyelenggaraan',
'Upd_Bypass_Link' => 'pautan pintasan',
'Upd_Guide_Wrong_Concurrent' => '{label} — mereka akan melihat {message} Hanya satu kemas kini boleh berjalan pada satu masa.',
'Upd_Another_Admin_Updating' => 'Pentadbir lain cuba mengemas kini pada masa yang sama',
'Upd_Guide_Backups_Title' => '4. Sandaran & pemulihan',
'Upd_Guide_Backups_Created' => 'Setiap kemas kini mencipta sandaran {before} menyentuh apa-apa: semua fail aplikasi yang boleh diganti oleh kemas kini, salinan {env}, dan longgokan pangkalan data penuh. Muat naik dan {storage} tidak pernah diubah oleh kemas kini dan oleh itu bukan sebahagian daripadanya — simpan sandaran anda sendiri untuknya. Sandaran disimpan dalam {path} dan tidak pernah boleh diakses dari web.',
'Upd_Before' => 'sebelum',
'Upd_Guide_Backups_Panel' => 'Panel {panel} pada tab {tab} menyenaraikannya dengan tarikh, versi dan saiz. Dari situ anda boleh {restore} mana-mana sandaran lengkap (fail + pangkalan data — salinan keselamatan pangkalan data semasa diambil terlebih dahulu) atau {delete} yang lama.',
'Upd_Restore_Verb' => 'memulihkan',
'Upd_Delete_Verb' => 'memadam',
'Upd_Guide_Backups_Retention' => 'Gunakan {keep} untuk memilih bilangan sandaran yang disimpan; yang lebih lama dibuang secara automatik selepas setiap kemas kini yang berjaya. Satu-satunya sandaran lengkap yang tinggal tidak boleh dipadam — anda sentiasa mempunyai jalan kembali.',
'Upd_Guide_Manual_Title' => '5. Kemas kini manual (kaedah sandaran)',
'Upd_Guide_Manual_Text' => 'Jika anda lebih suka mengemas kini secara manual, atau pemuat naik tidak boleh digunakan pada pelayan anda, ikut arahan langkah demi langkah pada tab {tab} halaman ini.',
'Upd_Guide_Clear_Cache_First' => 'Jika halaman kelihatan rosak atau kosong selepas sebarang kemas kini, kosongkan cache pelayar anda terlebih dahulu — itu hampir selalu puncanya.',
'Upd_Restore_Backup_Confirm' => 'Pulihkan sandaran ini? Fail semasa dan pangkalan data semasa akan diganti dengan sandaran. Salinan keselamatan pangkalan data semasa diambil terlebih dahulu. (v{version} — {date})',
'Woo_Guide_Lead' => 'Cara kedai WooCommerce kekal selaras dengan ERP. Baris cron di bawah dibina untuk pelayan ini, jadi ia boleh disalin terus ke dalamnya.',
'Woo_Guide_Ways_Note' => 'Tidak seperti Shopify, WooCommerce tidak menghantar apa-apa ke ERP dengan sendirinya — tiada penerima webhook di sini, jadi semua data {in} tiba mengikut jadual. Hanya stok {out} boleh dihantar serta-merta.',
'Woo_In' => 'masuk',
'Woo_Out' => 'keluar',
'Woo_Guide_Both_Ways_Title' => 'Kedua-dua arah memerlukan ini dahulu',
'Woo_Api_Keys' => 'Kunci API',
'Woo_Guide_Api_Keys_Text' => '{path}, kebenaran {perm}. Salin kunci pengguna dan rahsia ke tab {settings}, bersama URL kedai — alamat laman anda tanpa garis condong di hujung, cth. {example}.',
'Woo_Credentials_Saved' => 'bukti kelayakan disimpan',
'Woo_Not_Configured_Yet' => 'belum dikonfigurasi',
'Woo_Guide_Wp_App_Password_Title' => 'Kata laluan aplikasi WordPress (pilihan)',
'Woo_Guide_Wp_App_Password_Text' => 'Hanya digunakan untuk imej produk. API WooCommerce memindahkan produk, stok, kategori, jenama, pelanggan dan pesanan; API WordPress yang mencari Pustaka Media dan memuat naik imej yang belum ada di sana.',
'Woo_Guide_Wp_App_Password_Note' => 'Gunakan pengguna WordPress yang boleh mengurus media, dan cipta kata laluan di bawah {path}. Biarkan kedua-dua medan kosong dan semuanya masih disegerakkan — hanya lampiran imej dilangkau.',
'Woo_Guide_Pick_Way_Title' => 'Kemudian pilih cara ia kekal selaras',
'Woo_Right_Away' => 'Serta-merta',
'Woo_Stock_Live' => 'stok langsung',
'Woo_Stock_Not_Live' => 'stok tidak langsung',
'Woo_Guide_Realtime_Lead' => 'Satu arah sahaja: stok dan produk yang keluar dari ERP. Pesanan dan suntingan produk yang dibuat dalam WooCommerce masih tiba mengikut jadual — lihat tab lain.',
'Woo_Push_Stock_On_Change' => 'Hantar stok sebaik sahaja ia berubah',
'Woo_Setting_People_Miss' => 'Ini tetapan yang sering terlepas pandang',
'Woo_Guide_Pos_Sale_Not_Reach' => 'Jualan POS {not} sampai ke WooCommerce dengan sendirinya. Jika dimatikan, kedai hanya mengetahuinya pada penyegerakan stok seterusnya — sejam, secara lalai — dan dalam tempoh itu ia boleh menjual unit yang telah anda jual di kaunter.',
'Woo_Does_Not' => 'tidak',
'Woo_Guide_Tick_Instant' => 'Tandakan {option} pada tab {settings}. Itu sahaja persediaannya — tiada pekerja, tiada cron. Setiap jualan, pemulangan, pelarasan, pemindahan dan pembelian yang diterima kemudian menghantar push bagi produk tersebut sahaja, sejurus selepas jualan disimpan, dan jualan dua puluh baris hanya memerlukan satu push, bukan dua puluh. Kaunter tidak pernah menunggunya.',
'Woo_Currently' => 'Pada masa ini:',
'Woo_Instant_On_Text' => 'hidup — stok dihantar apabila berubah',
'Woo_Instant_Off_Text' => 'mati — stok mengikut jadual sahaja',
'Woo_Guide_Instant_Note' => 'Hanya produk yang sudah dipautkan ke WooCommerce dihantar — produk yang tidak pernah disegerakkan tiada apa-apa di kedai untuk dibetulkan. Produk berubah dihantar melalui induknya, dan kombo dihantar semula apabila mana-mana komponennya bergerak. Operasi pukal (memadam produk, menetapkan semula gudang) menulis stok tanpa mencetuskan peristiwa, yang merupakan satu sebab untuk turut mengekalkan penyegerakan stok setiap jam.',
'Woo_Push_Products_On_Save' => 'Hantar produk sebaik sahaja ia disimpan',
'Woo_Guide_Tick_Auto_Products' => 'Tandakan {option} pada tab {settings} dan produk yang dicipta, diedit atau diduplikasi dalam Stocky dihantar ke WooCommerce sejurus selepas ia disimpan — butiran, harga, varian dan imej, kemudian stoknya. Produk baharu dicipta di kedai serta-merta dan bukannya menunggu penyegerakan produk setiap malam.',
'Woo_On' => 'hidup',
'Woo_Off' => 'mati',
'Woo_Guide_Bulk_Imports_Note' => 'Import pukal tidak dihantar satu demi satu — jalankan penyegerakan produk selepas import. Segerakkan kategori dan jenama dahulu, supaya produk yang dihantar masuk ke kategori yang betul.',
'Woo_Nothing_Else_To_Install' => 'Tiada apa-apa lagi untuk dipasang',
'Woo_Guide_Same_Process' => 'Tiada pekerja baris gilir, tiada entri cron. Push berjalan dalam proses yang sama yang melayan jualan, {after} respons dihantar kembali, jadi kaunter tidak pernah menunggu WooCommerce. Push tidak pernah bertindih: perubahan yang dibuat semasa satu push berjalan akan menunggunya dan dihantar sejurus selepasnya.',
'Woo_After' => 'selepas',
'Woo_Guide_Shop_Stops_Answering' => 'Kedai yang berhenti menjawab akan diabaikan selepas lapan saat, dan push dijeda selama lima minit supaya setiap jualan tidak menunggunya lagi; perubahan yang masuk dalam tempoh itu dihantar bersama push pertama selepas jeda, dan penyegerakan stok setiap jam tetap akan mengejar. Setiap jeda direkodkan dalam tab Log.',
'Woo_Guide_Artisan_Exception' => 'Satu pengecualian: perubahan stok yang dibuat oleh arahan artisan tiada respons untuk diikuti, jadi ia dimasukkan ke baris gilir {queue}. Untuk menghantarnya dengan segera juga, kosongkan baris gilir itu:',
'Woo_Cron_Line_Copied' => 'Baris cron disalin',
'Woo_Command_Copied' => 'Arahan disalin',
'Woo_Guide_Not_Woo_Queue' => 'Sengaja bukan baris gilir {queue}: baris gilir itu membawa kelompok katalog yang mengambil masa berjam-jam, dan push serta-merta yang beratur di belakangnya tidak akan serta-merta.',
'Woo_On_A_Schedule' => 'Mengikut jadual',
'Woo_Guide_Scheduled_Lead' => 'Semuanya disemak semula dari semasa ke semasa, kedua-dua arah. Beginilah cara pesanan sampai ke ERP, cara katalog diterbitkan, dan apa yang membaiki apa-apa yang terlepas oleh laluan pantas. Setiap kerja mendapat entri cron sendiri, jadi anda hanya menjalankan apa yang anda mahu.',
'Woo_Guide_Sync_Drains_Queue' => '{command} mengosongkan baris gilirnya sendiri semasa ia berjalan, jadi baris ini tidak memerlukan pekerja berasingan. Pada Windows, gunakan Task Scheduler dengan program {program} dan argumen yang sama, dimulakan dalam {path}.',
'Woo_Or_No_Cron' => 'Atau tanpa cron langsung',
'Woo_Guide_No_Cron_Text' => 'Setiap tab di sini menyegerak atas permintaan, dan penyegerakan manual mengosongkan kelompoknya sendiri semasa halaman dibuka — jadi kedai kecil boleh berjalan tanpa sebarang entri cron. Apa yang anda hilang ialah semua yang berlaku semasa tiada siapa memerhati: pesanan hanya tiba apabila seseorang menekan butang.',
'Woo_Commands_Worth_Knowing' => 'Arahan yang patut diketahui',
'Woo_Worth_Knowing' => 'Patut diketahui',
'Woo_Guide_Changing_Url_Clears' => 'Menukar URL kedai atau kunci API mengosongkan setiap pemetaan — produk, kategori, jenama dan pelanggan semuanya disegerakkan semula ke kedai baharu.',
'Woo_Guide_Keep_Skus' => 'Pastikan SKU konsisten antara Stocky dan WooCommerce: itulah yang menghalang pendua dan menjadikan pemautan semula selamat.',
'Woo_Guide_Stock_Total' => 'Stok yang diterbitkan ke Woo ialah {total}, bukan angka satu gudang.',
'Woo_Total_Across_Warehouses' => 'jumlah merentasi setiap gudang',
'Woo_Guide_Full_Reference' => 'Rujukan penuh — setiap skop, cara baris gilir berfungsi, dan senarai penyelesaian masalah — ada dalam {file}.',
'Woo_Way_Covers' => 'Meliputi',
'Woo_Way_Covers_Realtime' => 'Stok yang keluar dari ERP sahaja — jualan POS, pemulangan, pelarasan, pembelian yang diterima',
'Woo_Way_Covers_Scheduled' => 'Semuanya, kedua-dua arah: pesanan dan perubahan produk masuk, katalog dan stok keluar',
'Woo_Way_Speed' => 'Kelajuan',
'Woo_Way_Seconds' => 'Saat',
'Woo_Way_Speed_Scheduled' => 'Apa sahaja yang anda masukkan dalam entri cron (stok setiap jam, pesanan setiap 15 min)',
'Woo_Way_Needs' => 'Keperluan',
'Woo_Way_Needs_Realtime' => 'Tiada — hanya tetapan',
'Woo_Way_Needs_Scheduled' => 'Satu entri cron bagi setiap kerja — atau tiada, jika anda menyegerak secara manual',
'Woo_Way_Switched_On_At' => 'Dihidupkan di',
'Woo_Way_Cron_Entries_Below' => 'Entri cron di bawah',
'Woo_Cron_Orders' => 'Pesanan setiap 15 minit — hanya yang berubah sejak larian terakhir.',
'Woo_Cron_Products_Pull' => 'Perubahan produk daripada kedai, setiap malam pada 03:00.',
'Woo_Cron_Customers' => 'Pelanggan, setiap malam pada 03:30.',
'Woo_Cron_Stock' => 'Stok setiap jam — jaring keselamatan di bawah push serta-merta, dan satu-satunya penyegerakan stok tanpanya.',
'Woo_Cron_Products_Push' => 'Produk yang belum dipautkan, setiap malam pada 02:00. Produk sedia ada tidak ditulis semula.',
'Woo_Cmd_Stock' => 'Hantar stok untuk setiap produk yang dipautkan sekarang.',
