'Woo_Cmd_Orders_Full' => 'Imbas semula setiap pesanan dan bukan hanya perubahan terkini.',
'Woo_Cmd_Pull' => 'Semua yang masuk sekali gus: produk, pesanan, pelanggan.',
'Woo_Guide_Page_Title' => 'Panduan WooCommerce',
'Woo_Guide_Page_Subtitle' => 'Menyambungkan kedai, apa yang berjalan dengan sendirinya, dan entri cron untuk pelayan ini',
'Woo_Settings_Button' => 'Tetapan WooCommerce',
'Woo_No_Shop_Connected' => 'Belum ada kedai disambungkan',
'Woo_No_Shop_Connected_Desc' => 'Semua di bawah masih terpakai — masukkan URL kedai dan kunci API pada halaman tetapan WooCommerce, kemudian kembali.',
