'Shopify_Could_Not_Load_Store' => 'Tidak dapat memuatkan kedai ini',
'Shopify_G_Lead_Store' => 'Apa yang diperlukan oleh kedai ini untuk kekal selaras. Semua di sini khusus untuk kedai ini — laluan dan id adalah sebenar, jadi arahan boleh disalin terus ke pelayan.',
'Shopify_G_Lead_Generic' => 'Cara kedai Shopify kekal selaras dengan ERP. Pilih kedai di atas untuk melihat keadaannya sendiri, atau bacanya seadanya — baris cron dan URL webhook adalah sama tidak kira kedai mana yang anda sambungkan.',
'Shopify_G_Ways_Note' => 'Kebanyakan kedai menjalankan kedua-duanya: yang pertama memastikan kedai terkini dari minit ke minit, yang kedua menangkap apa sahaja yang terlepas oleh yang pertama — webhook yang tidak pernah sampai, suntingan yang dibuat terus dalam pentadbir Shopify, malam ketika laman tidak berfungsi.',
'Shopify_G_Both_Need' => 'Kedua-dua arah memerlukan ini dahulu',
'Shopify_G_Credentials' => 'Bukti kelayakan Shopify',
'Shopify_G_Cred_Intro' => 'Sejak Januari 2026 Shopify tidak lagi mencipta aplikasi tersuai di dalam pentadbir, jadi terdapat dua jenis sambungan:',
'Shopify_G_Cred_DevDash' => '{app} (mana-mana kedai yang disambungkan sekarang) — {path}. Berikan skop Admin API untuk apa yang disegerakkan oleh kedai ini, pasang aplikasi pada kedai, kemudian salin {clientId} dan {clientSecret} dari halaman Settings aplikasi ke dalam {where}. ERP menukarkannya kepada token akses sendiri dan memperbaharuinya sebelum tamat tempoh setiap 24 jam. Client secret juga menandatangani webhook, jadi tiada apa-apa lagi diperlukan. Aplikasi dan kedai mesti berada dalam organisasi Shopify yang sama.',
'Shopify_G_Dev_Dashboard_App' => 'Aplikasi Dev Dashboard',
'Shopify_G_Cred_Legacy' => '{app} (dicipta dalam pentadbir sebelum 2026) — terus berfungsi tanpa perubahan dengan {token} ({prefix}) dan {secret} sebagai rahsia tandatangan webhook. Bukan nilai yang sama dengan token, dan menukar kedua-duanya secara terbalik ialah sebab biasa webhook ditolak.',
'Shopify_G_Legacy_App' => 'Aplikasi tersuai lama',
'Shopify_G_API_Secret_Key' => 'Kunci rahsia API',
'Shopify_G_Stored' => 'disimpan',
'Shopify_G_Missing_Refused' => 'tiada — penghantaran akan ditolak',
'Shopify_G_Where_Data_Desc' => '{path} Gudang ERP yang stoknya dijual oleh kedai ini, dan lokasi Shopify tempat stok itu ditulis. Penyegerakan inventori dan import pesanan kedua-duanya enggan berjalan tanpanya.',
'Shopify_G_Currently' => 'Pada masa ini: gudang {warehouse}, lokasi {location}',
'Shopify_G_Not_Set_Lower' => 'tidak ditetapkan',
'Shopify_G_Ready' => 'sedia',
'Shopify_G_Incomplete' => 'tidak lengkap',
'Shopify_G_Manual_Syncs' => 'Penyegerakan yang anda mulakan secara manual',
'Shopify_G_Manual_Desc' => 'Penyegerakan yang dimulakan dari {centre} menjawab serta-merta dan berjalan di latar belakang, dalam kepingan pendek yang masing-masing diteruskan dari tempat yang terakhir berhenti. Katalog besar tidak pernah terputus separuh jalan oleh pengehosan yang menamatkan permintaan web yang panjang (LiteSpeed, nginx, pengimbang beban), dan menutup halaman tidak menghentikannya. Pekerja untuk itu ialah satu lagi baris cron:',
'Shopify_G_Cron_Copied' => 'Baris cron disalin',
'Shopify_G_Manual_Note' => 'Tanpanya penyegerakan masih selesai, tetapi hanya semasa halaman Pusat Penyegerakan kekal terbuka: apabila tiada pekerja mengambil larian dalam beberapa saat, halaman itu sendiri meneruskannya, satu permintaan pendek pada satu masa. Pada Windows gunakan Task Scheduler setiap minit: program {program}, argumen {args}, dimulakan dalam {dir}.',
'Shopify_G_Then_Pick' => 'Kemudian pilih cara ia kekal selaras',
'Shopify_G_Right_Away' => 'Serta-merta',
'Shopify_G_Stock_Live' => 'stok langsung',
'Shopify_G_Stock_Not_Live' => 'stok tidak langsung',
'Shopify_G_Realtime_Lead' => 'Setiap perubahan dihantar sebaik sahaja ia berlaku, dalam beberapa saat. Dua bahagian, dan ia adalah suis berasingan: {webhooks} membawa peristiwa kedai sendiri masuk, dan {push} menghantar stok keluar.',
'Shopify_G_Webhooks_Lower' => 'webhook',
'Shopify_G_Instant_Push_Lower' => 'push stok serta-merta',
'Shopify_G_Webhooks_In' => 'Webhook — kedai → ERP',
'Shopify_G_Webhooks_Desc' => 'Pesanan, perubahan status pesanan, dan suntingan produk, pelanggan dan stok yang dibuat dalam Shopify. Buka kedai dan tekan {button} pada {tab}nya — selamat ditekan dua kali. Shopify menghantar ke:',
'Shopify_G_Webhooks_Tab' => 'Tab Webhook',
'Shopify_G_Webhooks_Note' => 'Alamat mesti boleh dicapai dari internet melalui HTTPS — Shopify tidak akan menghantar ke {localhost} atau domain {test}. Setiap penghantaran direkodkan sekali, jadi percubaan semula Shopify tidak boleh mencipta pesanan pendua, dan yang gagal boleh dimainkan semula. Penghantaran ditolak sehingga rahsia tandatangan dari langkah 1 disimpan.',
'Shopify_G_Instant_Out' => 'Push stok serta-merta — ERP → kedai',
'Shopify_G_Setting_Missed' => 'Ini tetapan yang sering terlepas pandang',
'Shopify_G_Pos_Not_Auto' => 'Jualan POS {not} sampai ke Shopify dengan sendirinya. Jika dimatikan, kedai hanya mengetahuinya pada langkah push Inventori seterusnya — dan dalam tempoh itu ia boleh menjual unit yang telah anda jual di kaunter.',
'Shopify_G_Not' => 'tidak',
'Shopify_G_Tick_Push' => 'Tandakan {setting} pada {where}. Itu sahaja persediaannya — tiada pekerja, tiada cron. Setiap jualan, pemulangan dan pelarasan kemudian menghantar push bagi produk tersebut sahaja, sejurus selepas jualan disimpan, dan jualan dua puluh baris hanya memerlukan satu push, bukan dua puluh. Kaunter tidak pernah menunggunya.',
'Shopify_G_This_Store' => 'Kedai ini:',
'Shopify_G_Push_On' => 'hidup — stok dihantar apabila berubah',
'Shopify_G_Push_Off' => 'mati — stok mengikut jadual sahaja',
'Shopify_G_Push_Note' => 'Hanya produk yang sudah mempunyai pemetaan Shopify, dan hanya pergerakan dalam gudang kedai ini, dihantar. Operasi pukal — memadam produk, menetapkan semula gudang — menulis stok tanpa mencetuskan peristiwa, yang merupakan satu sebab untuk turut mengekalkan langkah inventori berjadual.',
'Shopify_G_Nothing_Install' => 'Tiada apa-apa lagi untuk dipasang',
'Shopify_G_No_Worker_Note' => 'Kedua-dua bahagian tidak memerlukan pekerja baris gilir atau entri cron. Webhook yang masuk dikendalikan dalam permintaan yang dibuat oleh Shopify; push stok yang keluar berjalan dalam proses yang sama yang melayan jualan, {after} respons dihantar kembali — jadi kaunter tidak pernah menunggu Shopify, dan kedai yang berhenti menjawab akan diabaikan selepas sepuluh saat dan diserahkan kepada push inventori berjadual seterusnya.',
'Shopify_G_After' => 'selepas',
'Shopify_G_Artisan_Note' => 'Satu pengecualian: perubahan stok yang dibuat oleh arahan artisan tiada respons untuk diikuti, jadi ia dimasukkan ke baris gilir {queue}. Jika anda mahu menghantarnya dengan segera juga, kosongkan baris gilir itu:',
'Shopify_G_On_Schedule' => 'Mengikut jadual',
'Shopify_G_On_Lower' => 'hidup',
'Shopify_G_Off_Lower' => 'mati',
'Shopify_G_Scheduled_Lead' => 'Semuanya disemak semula dari semasa ke semasa, kedua-dua arah. Lebih perlahan daripada masa nyata, tetapi inilah yang menghantar stok keluar pada kedai yang tidak menggunakan push serta-merta, yang menangkap webhook yang terlepas, dan satu-satunya cara untuk memindahkan keseluruhan katalog.',
'Shopify_G_Cron_Entry' => 'Entri cron',
'Shopify_G_Cron_Entry_Desc' => 'Tiada apa-apa yang berjadual berjalan tanpanya. Satu baris, modul ini sahaja — tambahkannya di sebelah apa sahaja yang telah anda pilih untuk dijadualkan:',
'Shopify_G_Cron_Note' => 'Setiap lima minit ialah resolusi paling halus yang boleh digunakan oleh pelan, kerana lima minit ialah selang langkah terpendek. Entri yang lebih kasar hanya menjadi had bawah — dengan {example}, langkah yang ditetapkan kepada 5 minit berjalan setiap 15. Pada Windows gunakan Task Scheduler: program {program}, argumen {args}, dimulakan dalam {dir}.',
'Shopify_G_Switch_On_Plan' => 'Hidupkannya, dan pilih pelan',
'Shopify_G_Plan_Desc' => '{where} Suis menentukan sama ada cron boleh bertindak sama sekali; pelan menentukan apa yang dilakukannya. {step} ialah satu entiti dalam satu arah dengan selangnya sendiri — {first}, {second}. Selang lalai digunakan oleh mana-mana langkah yang membiarkan kotaknya sendiri kosong.',
'Shopify_G_Step_Lower' => 'langkah',
'Shopify_G_Plan_Note' => 'Biarkan pelan kosong dan kedai menarik pesanan dan menghantar stok pada selang lalai, iaitu apa yang dikehendaki oleh kebanyakan kedai. Pesanan hanya ditarik: Shopify ialah tempat pelanggan membuat pesanan.',
'Shopify_G_Schedule_On' => 'jadual hidup',
'Shopify_G_Schedule_Off' => 'jadual mati — manual sahaja',
'Shopify_G_When_Step_Runs' => 'Bila langkah sebenarnya berjalan',
'Shopify_G_When_Note' => 'Langkah perlu dijalankan apabila langkah yang sama kali terakhir {started} lebih lama daripada selangnya, dibaca daripada sejarah larian. Jadi penyegerakan yang anda mulakan secara manual menangguhkan yang automatik seterusnya, dan langkah yang terus gagal dicuba semula mengikut selangnya dan bukannya setiap detik. Gambaran Keseluruhan kedai memaparkan larian terakhir setiap langkah, masa perlu dijalankan seterusnya, dan sebab ia disekat apabila berlaku. Jalankan push katalog pertama secara manual — dengan {dryRun} dahulu — sebelum meletakkannya pada jadual.',
'Shopify_G_Started_Lower' => 'dimulakan',
'Shopify_G_Where_Setting' => 'Di mana setiap tetapan berada',
'Shopify_G_Where_Setting_Note' => 'Semua ini berada pada kedai sedia ada: {path}, kemudian pensel (atau {edit} pada halaman kedai itu sendiri).',
'Shopify_G_Product_Images' => 'Imej produk',
'Shopify_G_Img_1' => 'Gambar dihantar bersama produk pada {push} — imej utama dahulu, kemudian galeri, kemudian satu bagi setiap varian yang mempunyai imejnya sendiri, sehingga lima puluh.',
'Shopify_G_Products_Push' => 'push produk',
'Shopify_G_Img_2' => 'Gambar varian dimuat naik bersama produk dan kemudian {assigned}, iaitu cara Shopify memodelkannya: varian menunjuk kepada salah satu imej produk. Varian yang menggunakan semula imej utama tidak memuat naiknya dua kali.',
'Shopify_G_Assigned' => 'ditetapkan kepada varian tersebut',
'Shopify_G_Img_3' => 'Imej yang disimpan sebagai fail {uploaded} ke Shopify, bukan dipautkan, jadi ia berfungsi walaupun pemasangan ini tidak boleh dicapai dari internet. Imej yang ditambah sebagai pautan yang ditampal diserahkan kepada Shopify sebagai URL tersebut, yang mesti boleh dicapai secara umum.',
'Shopify_G_Uploaded' => 'dimuat naik',
'Shopify_G_Img_4' => 'Ia hanya dihantar semula apabila benar-benar berubah — push yang hanya mengubah harga tidak menyentuh imej kedai, kerana menghantarnya akan menggantikan keseluruhan set.',
'Shopify_G_Img_5' => 'Membuang imej dalam ERP {not} memadamnya dalam Shopify. Padamkannya di sana juga, atau kedai akan terus memaparkannya.',
'Shopify_G_Commands' => 'Arahan yang patut diketahui',
'Shopify_G_Command_Copied' => 'Arahan disalin',
'Shopify_G_Foot' => 'Setiap penyegerakan menulis ke {logs}, dan Gambaran Keseluruhan setiap kedai memaparkan bila setiap langkah terakhir berjalan, bila ia perlu dijalankan seterusnya, dan apa yang menyekatnya apabila ada. Di situlah tempat pertama untuk dilihat apabila penyegerakan tidak berlaku seperti yang dijangka.',
'Shopify_G_Covers' => 'Meliputi',
'Shopify_G_Covers_Rt' => 'Pesanan dan suntingan yang dibuat dalam Shopify; stok yang keluar dari ERP (jualan POS, pemulangan, pelarasan)',
'Shopify_G_Covers_Sch' => 'Semuanya, kedua-dua arah — termasuk push katalog dan apa-apa yang terlepas oleh laluan pantas',
'Shopify_G_Speed' => 'Kelajuan',
'Shopify_G_Speed_Rt' => 'Saat',
