'Shopify_G_Needs' => 'Keperluan',
'Shopify_G_Needs_Rt' => 'Alamat HTTPS awam dan rahsia tandatangan untuk webhook masuk. Stok keluar tidak memerlukan apa-apa langsung',
'Shopify_G_Needs_Sch' => 'Entri cron yang menjalankan {cmd}',
'Shopify_G_Switched_On_At' => 'Dihidupkan di',
'Shopify_G_On_Sch' => '{path}, serta pelan',
'Shopify_G_Scope_Orders' => '{scope} ({extra} untuk pesanan lebih daripada 60 hari)',
'Shopify_G_Admin_Scopes' => 'Skop Admin API',
