'Shopify_G_Set_Credentials' => 'Client ID + secret atau token akses, rahsia tandatangan, versi API',
'Shopify_G_Set_Credentials_What' => 'Bukti kelayakan daripada aplikasi Shopify (Dev Dashboard atau aplikasi tersuai lama).',
'Shopify_G_Set_Targets' => 'Gudang ERP, lokasi Shopify',
'Shopify_G_Set_Targets_What' => 'Stok mana yang dijual oleh kedai ini, dan di mana pesanan difailkan.',
