'Shopify_G_Set_Create_Missing_What' => 'Sama ada tarikan boleh mencipta rekod ERP yang tidak dapat dipadankan.',
'Shopify_G_Set_Entities' => 'Entiti mana yang disegerakkan sama sekali',
