'StoreAdm_Stock_Required_Available' => '{name}: Diperlukan {need} — Tersedia {have}',
'StoreAdm_PG_Intro_Msg' => 'PayPal, Paystack, Flutterwave, Razorpay, bKash dan SSLCommerz digunakan oleh pembayaran KEDAI DALAM TALIAN sahaja.',
'StoreAdm_PG_Intro_Desc' => 'Kunci Stripe dikongsi secara global (pentadbir dan kedai dalam talian menggunakan integrasi Stripe yang sama). Setiap tab menghidupkan atau mematikan kaedahnya untuk pembayaran kedai dalam talian; Pembayaran Luar Talian mengandungi kaedah yang dibayar di luar sistem.',
'StoreAdm_PG_Used_By_Store_Only' => 'Digunakan oleh pembayaran kedai dalam talian sahaja',
