'StoreAdm_PG_Gw_Secret' => 'Rahsia {gw}',
'StoreAdm_PG_Cards_Off' => 'Pembayaran kad dimatikan',
'StoreAdm_PG_Cards_Off_Desc' => 'Kunci anda dikekalkan — pembayaran kedai dalam talian hanya berhenti menawarkan pilihan kad sehingga anda menghidupkannya semula.',
'StoreAdm_PG_No_Stripe_Key' => 'Tiada kunci Stripe disimpan',
'StoreAdm_PG_No_Stripe_Key_Desc' => 'Masukkan kunci dan rahsia Stripe anda untuk mula menerima pembayaran kad di kedai dalam talian.',
'StoreAdm_PG_Gw_Client_Id' => 'Client ID {gw}',
'StoreAdm_PG_Gw_Client_Secret' => 'Client Secret {gw}',
'StoreAdm_PG_Sandbox' => 'Sandbox (mod ujian)',
'StoreAdm_PG_Sandbox_Paypal_Hint' => 'HIDUP menggunakan {sandbox} dengan bukti kelayakan sandbox; MATIKAN untuk mengecaj akaun sebenar di {live}.',
'StoreAdm_PG_Gw_Webhook_Id_Opt' => 'Webhook ID {gw} (pilihan)',
'StoreAdm_PG_Paypal_Webhook_Hint' => 'Sandaran untuk pembayaran yang ubah hala pelayarnya tidak pernah sampai, serta bayaran balik/caj balik. Daftarkan webhook di {site} yang menunjuk ke URL di bawah (peristiwa: {events}) dan tampal Webhook ID di sini.',
'StoreAdm_PG_Webhook_Url' => 'URL Webhook:',
'StoreAdm_PG_Gw_Disabled' => '{gw} dilumpuhkan',
'StoreAdm_PG_Paypal_Disabled_Desc' => 'Hidupkan PayPal dan masukkan Client ID dan Secret aplikasi REST anda (dari {site}) untuk membolehkan pelanggan membayar dengan PayPal semasa pembayaran kedai dalam talian.',
'StoreAdm_PG_Gw_Public_Key' => 'Kunci Awam {gw}',
'StoreAdm_PG_Gw_Secret_Key' => 'Kunci Rahsia {gw}',
'StoreAdm_PG_Paystack_Test_Live' => 'Ujian vs langsung ditentukan oleh pasangan kunci: kunci {test} berjalan dalam mod ujian, kunci {live} mengecaj kad sebenar — tiada suis sandbox berasingan.',
'StoreAdm_PG_Paystack_Webhook_Url' => 'URL Webhook (sandaran pilihan — tetapkannya di bawah Settings → API Keys & Webhooks pada papan pemuka Paystack; permintaan disahkan HMAC dengan kunci rahsia anda):',
'StoreAdm_PG_Paystack_Disabled_Desc' => 'Hidupkan Paystack dan masukkan kunci Awam dan Rahsia anda (dari {site} → Settings → API Keys) untuk menerima kad, pindahan bank dan wang mudah alih semasa pembayaran kedai dalam talian.',
'StoreAdm_PG_Secret_Hash_Opt' => 'Secret Hash (webhook, pilihan)',
'StoreAdm_PG_Flutterwave_Hash_Hint' => 'Secret Hash yang anda tetapkan di bawah Settings → Webhooks pada papan pemuka Flutterwave; webhook masuk ditolak melainkan pengepala {header} sepadan.',
'StoreAdm_PG_Flutterwave_Info' => 'Menggunakan API Flutterwave v3 dengan kunci klasik. Ujian vs langsung ditentukan oleh pasangan kunci ({keys} vs kunci langsung) — tiada suis sandbox berasingan. Mata wang kedai mesti didayakan pada akaun Flutterwave anda.',
'StoreAdm_PG_Flutterwave_Webhook_Url' => 'URL Webhook (sandaran pilihan — tetapkannya dengan Secret Hash di atas pada papan pemuka Flutterwave):',
'StoreAdm_PG_Flutterwave_Disabled_Desc' => 'Hidupkan Flutterwave dan masukkan kunci Awam dan Rahsia v3 anda (dari {site} → Settings → API) untuk menerima kad, wang mudah alih dan pindahan bank semasa pembayaran kedai dalam talian.',
'StoreAdm_PG_Gw_Key_Id' => 'Key ID {gw}',
'StoreAdm_PG_Gw_Key_Secret' => 'Key Secret {gw}',
'StoreAdm_PG_Webhook_Secret_Opt' => 'Rahsia Webhook (pilihan)',
'StoreAdm_PG_Razorpay_Secret_Hint' => 'Rahsia yang anda tentukan semasa mencipta webhook pada papan pemuka Razorpay; peristiwa masuk disahkan HMAC terhadapnya dan ditolak jika tidak sepadan.',
'StoreAdm_PG_Razorpay_Info' => 'Menggunakan Razorpay Payment Links (kad, UPI, perbankan internet, dompet). Ujian vs langsung ditentukan oleh pasangan kunci ({keys}) — tiada suis sandbox berasingan.',
'StoreAdm_PG_Razorpay_Webhook_Url' => 'URL Webhook (sandaran pilihan — daftarkannya dengan rahsia di atas di bawah Settings → Webhooks; peristiwa: {events}):',
