'Cr_Guide_Meaning' => 'Maksud',
'Cr_Guide_T_Statuses' => 'Status',
'Cr_Guide_Statuses_Note' => 'Status hanya bergerak ke hadapan, jadi kemas kini yang lewat tidak akan mengundurkan bungkusan. Bungkusan yang telah dihantar masih boleh dilaporkan sebagai sedang dipulangkan atau dipulangkan.',
'Cr_Guide_S_booked' => 'Kurier telah menerima pesanan; belum ada yang mengambilnya. Tempahan hanya boleh dibatalkan pada peringkat ini.',
'Cr_Guide_S_picked_up' => 'Kurier telah mengambil bungkusan.',
'Cr_Guide_S_in_transit' => 'Bergerak antara hab, dalam kastam atau ditahan.',
'Cr_Guide_S_out_for_delivery' => 'Bersama penghantar hari ini.',
'Cr_Guide_S_failed_attempt' => 'Tiada di rumah, ditolak atau alamat salah. Kurier akan mencuba lagi atau memulangkannya.',
'Cr_Guide_S_delivered' => 'Diserahkan kepada pelanggan. Amaun COD menjadi dikutip oleh kurier.',
'Cr_Guide_S_returning' => 'Dalam perjalanan pulang kepada anda.',
'Cr_Guide_S_returned' => 'Sudah kembali kepada anda: ia menunggu dalam Pulangan untuk disemak, atau dimasukkan semula ke stok secara automatik.',
'Cr_Guide_S_cancelled' => 'Tempahan telah dibatalkan.',
'Cr_Guide_T_Booking' => 'Menempah pesanan',
'Cr_Guide_B_Booking' => 'Hantar kepada kurier mengisi borang daripada jualan: penerima, alamat, amaun yang masih tertunggak sebagai COD, dan berat produk. Kurier yang mempunyai senarai bandar sendiri memaparkan pemilih, dan pilihan anda diingati untuk bandar tersebut. Agregator, DHL, FedEx, UPS dan Lalamove menawarkan Bandingkan kadar: pilih harga dan Tempah akan membelinya. Beberapa jualan boleh ditempah sekali gus daripada senarai jualan.',
'Cr_Guide_T_Cod' => 'Bayaran semasa penghantaran',
'Cr_Guide_B_Cod' => 'Bungkusan COD bergerak daripada Belum dikutip kepada Dikutip oleh kurier (semasa penghantaran) kepada Dibayar kepada anda. Kurier yang melaporkan bayaran menggerakkan langkah terakhir sendiri; bagi yang lain gunakan Kemas kini COD. Dengan akaun dipilih dalam Tetapan Kurier, bayaran direkodkan sebagai pembayaran pada jualan. Caj kurier boleh disimpan sebagai perbelanjaan setelah bungkusan selesai.',
'Cr_Guide_T_Returns' => 'Bungkusan dipulangkan',
'Cr_Guide_B_Returns' => 'Secara lalai, bungkusan yang dipulangkan menunggu dalam Penghantaran Kurier di bawah Pulangan untuk disemak. Masukkan Semula ke Stok mencipta pulangan jualan untuk keseluruhan pesanan dan memasukkan semula item ke dalam stok; Tolak tidak memasukkan apa-apa semula, untuk bungkusan yang rosak atau hilang. Tetapan Kurier boleh memasukkan semula ke stok secara automatik sebaliknya.',
'Cr_Guide_T_Customers' => 'Mesej pelanggan dan halaman penjejakan',
'Cr_Guide_B_Customers' => 'Pemberitahuan pelanggan dalam Tetapan Kurier menghantar SMS, e-mel atau WhatsApp pada status yang anda tandakan, sekali bagi setiap bungkusan, dengan teks anda sendiri. Halaman penjejakan dalam kedai dalam talian anda membolehkan pelanggan menjejak bungkusan melalui nombor penjejakan, atau nombor pesanan dan telefon. Pelanggan yang kerap memulangkan bungkusan mendapat lencana risiko pulangan semasa anda membuat tempahan.',
'Cr_Guide_T_Labels' => 'Label',
'Cr_Guide_B_Labels' => 'Cetak label memberikan label kurier sendiri apabila kurier mengeluarkannya (PDF, pautan atau imej), jika tidak, label Stocky dengan kod bar penjejakan dan amaun yang perlu dikutip. Benarkan tetingkap timbul untuk laman ini bagi mencetak. DHL, FedEx dan UPS memberikan label mereka sekali sahaja, semasa tempahan, dan Stocky menyimpannya untuk cetakan semula.',
'Cr_Guide_T_Faq' => 'Penyelesaian Masalah',
'Cr_Guide_Q_Test' => 'Uji sambungan gagal',
'Cr_Guide_A_Test' => 'Kunci mod ujian digunakan dengan mod Ujian dan kunci langsung dengan mod Langsung; ia berbeza. Buka Log kurier dan baca jawapan kurier untuk sebab yang tepat.',
'Cr_Guide_Q_City' => 'Kurier menolak bandar atau alamat',
'Cr_Guide_A_City' => 'Pilih bandar daripada senarai bandar kurier dalam borang tempahan; kurier hanya menerima nama mereka sendiri. Kurier yang menggunakan alamat pos juga memerlukan negeri, poskod dan kod negara dua huruf.',
'Cr_Guide_Q_Webhook' => 'Status tidak berubah dengan sendirinya',
'Cr_Guide_A_Webhook' => 'Bagi kurier yang menolak kemas kini, pastikan URL webhook didaftarkan di kurier: Log kurier menunjukkan setiap kemas kini yang diterima, atau sebab ia ditolak (contohnya rahsia yang salah). Kurier lain disemak mengikut jadual dalam Tetapan Kurier, dan Semak status sekarang akan bertanya serta-merta.',
'Cr_Guide_Q_Stuck' => 'Penghantaran menunjukkan ralat semakan status',
'Cr_Guide_A_Stuck' => 'Kurier menolak semakan terakhir; sebabnya ada pada penghantaran dan dalam Log kurier. Selepas kegagalan berulang, penghantaran tidak lagi disemak secara automatik: betulkan puncanya, kemudian gunakan Semak status sekarang.',
'Cr_Guide_Q_Label' => 'Tiada apa-apa dibuka semasa mencetak label',
'Cr_Guide_A_Label' => 'Pelayar anda menyekat tetingkap timbul. Benarkan tetingkap timbul untuk laman ini dan cuba lagi.',
'Cr_Guide_Q_Cod' => 'Bayaran COD tidak direkodkan pada jualan',
'Cr_Guide_A_Cod' => 'Dalam Tetapan Kurier, bayaran semasa penghantaran memerlukan suis dihidupkan dan akaun dipilih. Tanpa akaun, bayaran hanya ditandakan sebagai telah dibayar.',
