'Tfa_Guide_Codes_Title' => 'Simpan kod pemulihan',
'Tfa_Guide_Codes_Text' => 'Sejurus selepas persediaan, 8 kod pemulihan dipaparkan sekali. Setiap satu menggantikan kod telefon sebanyak sekali sahaja — untuk telefon yang hilang, rosak atau ditetapkan semula. Muat turun atau salin kod tersebut dan simpan di tempat yang selamat, jauh daripada telefon.',
'Tfa_Guide_Codes_Note' => 'Hampir habis? "Kod pemulihan baharu" pada profil menggantikan keseluruhan set; kod lama tidak lagi berfungsi.',
'Tfa_Guide_Signin_Title' => 'Log masuk',
'Tfa_Guide_Signin_Text' => 'Selepas e-mel dan kata laluan, halaman log masuk meminta kod semasa daripada aplikasi. Kod bertukar setiap 30 saat dan setiap satu hanya berfungsi sekali.',
'Tfa_Guide_Signin_Trust' => 'Menandakan "Jangan tanya lagi pada peranti ini" akan melangkau kod pada pelayar tersebut selama :days hari.',
'Tfa_Guide_Signin_Recovery' => 'Tiada telefon? Klik "Guna kod pemulihan" dan taip salah satu kod yang disimpan.',
'Tfa_Guide_Admin_Title' => 'Untuk pentadbir',
'Tfa_Guide_Require_Title' => 'Jadikannya wajib',
'Tfa_Guide_Require_Text' => 'Hidupkan "Wajibkan pengesahan dua faktor" pada kad ini, kemudian pilih peranan yang mesti menggunakannya — atau biarkan senarai kosong untuk setiap pengguna. Klik Hantar untuk menyimpan.',
'Tfa_Guide_Require_Next' => 'Tiada sesiapa yang dilog keluar. Pengguna yang belum mempunyai 2FA akan dibimbing melalui persediaan pada halaman log masuk pada log masuk seterusnya, sebelum mereka masuk, dan melihat kod pemulihan mereka di situ.',
'Tfa_Guide_Require_Note' => 'Pengguna yang diwajibkan tidak boleh mematikannya daripada profil mereka.',
'Tfa_Guide_Trust_Title' => 'Peranti dipercayai',
'Tfa_Guide_Trust_Text' => '"Ingat peranti dipercayai" menetapkan berapa lama pelayar boleh melangkau kod selepas log masuk berjaya. Pilih "Sentiasa minta kod" untuk komputer kongsi atau awam seperti POS di lantai kedai.',
'Tfa_Guide_Trust_Note' => 'Mengurangkan bilangan ini memendekkan tempoh peranti yang sudah dipercayai; mematikan atau menetapkan semula 2FA akan melupakan kesemuanya.',
'Tfa_Guide_Lost_Title' => 'Telefon hilang dan tiada kod pemulihan',
'Tfa_Guide_Lost_Text' => 'Pada halaman Pengguna, pengguna dengan 2FA menunjukkan "Hidup" dalam lajur 2FA. Butang perisai dalam Tindakan menetapkannya semula: pengguna log masuk dengan kata laluan sahaja dan menyediakan semula aplikasi (atau diminta berbuat demikian, jika ia diwajibkan).',
'Tfa_Guide_Lost_Warn' => 'Sahkan siapa yang membuat permintaan sebelum menetapkan semula — tetapan semula membuang perlindungan yang diberikan oleh 2FA kepada akaun tersebut.',
'Tfa_Guide_Open_Users' => 'Buka Pengguna',
'Tfa_Guide_Mobile_Title' => 'Aplikasi mudah alih dan API',
'Tfa_Guide_Mobile_Text' => 'Aplikasi mudah alih dan titik akhir token API meminta kod yang sama. Jika 2FA diwajibkan untuk pengguna yang belum menyediakannya, mereka mesti log masuk di web sekali untuk berbuat demikian.',
'Tfa_Guide_Protect_Title' => 'Perlindungan terbina dalam',
'Tfa_Guide_Protect_1' => '5 kod salah akan menyekat kemasukan kod bagi pengguna tersebut selama 15 minit, tanpa mengira tetapan sekatan di atas.',
'Tfa_Guide_Protect_2' => 'Setiap kod dan setiap kod pemulihan hanya berfungsi sekali.',
'Tfa_Guide_Protect_3' => 'Dengan "Rekod aktiviti log masuk" dihidupkan, kod salah dipaparkan dalam senarai Aktiviti log masuk sebagai "Kod 2FA salah".',
