'Tfa_Guide_Faq_Clock_A' => 'Jam telefon mungkin tidak tepat. Kod bergantung pada masa: tetapkan tarikh dan masa telefon kepada automatik (masa rangkaian), kemudian cuba kod seterusnya.',
'Tfa_Guide_Faq_Phone_Q' => 'Berpindah ke telefon baharu',
'Tfa_Guide_Faq_Phone_A' => 'Sama ada gunakan ciri pemindahan aplikasi pengesah itu sendiri, atau matikan 2FA pada profil dan hidupkan semula dengan telefon baharu (jika ia diwajibkan, minta pentadbir menetapkannya semula).',
'Tfa_Guide_Faq_Locked_Q' => '“Terlalu banyak kod tidak sah”',
