'Tfa_Guide_Rollout_2' => 'Beritahu pasukan anda aplikasi mana yang perlu dipasang dan bahawa persediaan mengambil masa seminit semasa log masuk.',
'Tfa_Guide_Rollout_3' => 'Hidupkan "Wajibkan pengesahan dua faktor", biarkan "Diwajibkan untuk" kosong (= setiap pengguna), dan pilih tempoh tangguh jika perlu. Klik Hantar.',
'Tfa_Guide_Rollout_4' => 'Klik "Log keluar pengguna tanpa 2FA" supaya mereka yang sudah log masuk menyediakannya sekarang dan bukannya pada log masuk yang akan datang. Anda kekal log masuk.',
'Tfa_Guide_Rollout_5' => 'Ikuti kemajuan dengan pembilang pada kad ini, atau penapis "Perlu persediaan" pada halaman Pengguna.',
'Tfa_Guide_Rollout_Note' => 'Dengan tempoh tangguh, skrin persediaan memaparkan “Ingatkan saya kemudian” sehingga tarikh akhir; selepas itu, persediaan diwajibkan untuk log masuk.',
'Tfa_Guide_Customers_Title' => 'Akaun pelanggan (kedai dan portal pelanggan)',
'Tfa_Guide_Customers_Text' => 'Pelanggan juga boleh melindungi akaun mereka sendiri. Ia adalah pilihan bagi setiap pelanggan dan tidak pernah dipaksa: hidupkannya di bawah Tetapan Kedai → Kawalan Akses Pendaftaran (kedai dalam talian) dan Portal Pelanggan → Tetapan Portal (portal pelanggan).',
'Tfa_Guide_Customers_1' => 'Pelanggan menghidupkannya daripada Akaun Saya (kedai) atau Profil (portal).',
'Tfa_Guide_Customers_2' => 'Mereka memilih kod yang dihantar melalui e-mel — paling mudah, tiada aplikasi diperlukan — atau aplikasi pengesah dengan kod pemulihan.',
'Tfa_Guide_Customers_3' => 'Kod melalui e-mel memerlukan tetapan mel yang berfungsi (Tetapan → Tetapan Mel). Kod tamat tempoh selepas 10 minit.',
'Tfa_Guide_Customers_4' => 'Mematikan pilihan ini kemudian akan menghentikan persediaan baharu; pelanggan yang sudah menggunakannya akan terus diminta kod dan boleh mematikannya sendiri.',
'Tfa_Required_Grace_Notice' => 'Pentadbir anda mewajibkan pengesahan dua faktor. Anda boleh menangguhkannya semasa log masuk sehingga :date; selepas itu, persediaan diwajibkan.',
